                nright=sum(1 for rr in range(H) for cc in range(c+1,W) if g[rr][cc] in wallset)
                dc=1 if nleft>nright else -1
                p=c+dc
                while 0<=p<W and out[p][r]==bg:
                    out[p][r]=marker; p+=dc
            elif hr:
                top=sum(1 for rr in range(r-1,-1,-1) for cc in range(W) if g[rr][cc] in wallset)
