def components(g):
    H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    seen=set(); runs=[]; singles=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen: continue
            v=g[r][c]; stack=[(r,c)]; comp={(r,c)}; seen.add((r,c))
            while stack:
                x,y=stack.pop()
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(x+dr,y+dc)
                    if 0<=p[0]<H and 0<=p[1]<W and p not in seen and g[p]==v:
                        seen.add(p); comp.add(p); stack.append(p)
            pts=list(comp)
            rows={p[0] for p in pts}; cols={p[1] for p in pts}
            if len(rows)==1 or len(cols)==1:
                runs.append(pts)
            else:
                singles+=pts
    return bg,runs,singles

